<?php require 'includes/db.php';require 'includes/helpers.php';require_login();ensure_default_categories($pdo);$msg='';if(isset($_GET['toggle'])){$pdo->prepare("UPDATE recurring SET active=1-active WHERE id=? AND user_id=?")->execute([(int)$_GET['toggle'],user_id()]);header('Location:recurring.php');exit;}if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM recurring WHERE id=? AND user_id=?")->execute([(int)$_GET['delete'],user_id()]);header('Location:recurring.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$title=trim($_POST['title']);$amount=(float)$_POST['amount'];$type=$_POST['type'];$cat=(int)$_POST['category_id'];$freq=$_POST['frequency'];$next=$_POST['next_date'];if($title&&$amount>0&&$cat&&$next){$pdo->prepare("INSERT INTO recurring(user_id,title,amount,type,category_id,frequency,next_date) VALUES(?,?,?,?,?,?,?)")->execute([user_id(),$title,$amount,$type,$cat,$freq,$next]);$msg='Recurring item added.';}}$cats=categories($pdo);$s=$pdo->prepare("SELECT r.*,c.name category,c.icon FROM recurring r JOIN categories c ON c.id=r.category_id WHERE r.user_id=? ORDER BY r.next_date");$s->execute([user_id()]);$items=$s->fetchAll(PDO::FETCH_ASSOC);?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recurring</title><link rel="stylesheet" href="assets/style.css"></head><body class="<?=!empty($_SESSION['dark'])?'dark':''?>"><div class="app"><aside class="sidebar"><?php include 'includes/nav.php';?></aside><main class="main"><header class="top"><div><h1>Recurring Transactions</h1><p>Keep subscriptions, salary and regular bills organized</p></div></header><div class="panel"><?php if($msg):?><div class="alert"><?=$msg?></div><?php endif;?><form method="post" class="formgrid"><label>Title<input name="title" placeholder="Netflix, Salary..." required></label><label>Amount<input name="amount" type="number" step=".01" min=".01" required></label><label>Type<select name="type"><option value="expense">Expense</option><option value="income">Income</option></select></label><label>Category<select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>"><?=h($c['icon'].' '.$c['name'])?></option><?php endforeach;?></select></label><label>Frequency<select name="frequency"><option>Monthly</option><option>Weekly</option><option>Yearly</option></select></label><label>Next date<input name="next_date" type="date" value="<?=date('Y-m-d')?>" required></label><div class="full actions"><button class="btn primary">Add Recurring Item</button></div></form></div><div class="panel" style="margin-top:18px"><?php foreach($items as $r):?><div class="tx"><div class="avatar"><?=h($r['icon'])?></div><div class="txbody"><b><?=h($r['title'])?></b><span><?=h($r['category'])?> · <?=h($r['frequency'])?> · Next <?=date('d M Y',strtotime($r['next_date']))?></span></div><b class="<?=$r['type']?>"><?=$r['type']==='income'?'+':'-'?>₹<?=money($r['amount'])?></b><a class="edit" href="?toggle=<?=$r['id']?>"><?=$r['active']?'Pause':'Resume'?></a><a class="delete" href="?delete=<?=$r['id']?>" onclick="return confirm('Delete this item?')">Delete</a></div><?php endforeach;?><?php if(!$items):?><div class="empty">No recurring transactions yet.</div><?php endif;?></div></main></div></body></html>